1	/*
2	 * Rounding — a single rule with two faces.
3	 *
4	 * Money is only ever settled in whole gold pieces, and a fraction of a gold
5	 * piece always falls to MHPCO. Which way that rounds depends on who is paying:
6	 * a premium the customer owes rounds up, a payout MHPCO owes rounds down.
7	 * Both functions below are that one rule; keep them together so a change of
8	 * heart about it is a change in one place.
9	 */
10	
11	/** Premiums are rounded up — the fraction falls to MHPCO. */
12	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
13	
14	/** Payouts are rounded down — the fraction stays with MHPCO. */
15	const roundPayoutDown = (amount: number): number => Math.floor(amount);
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type QuoteStep = { op: string; items: Item[] };
25	
26	export type Damage = { itemType: string; amount: number };
27	
28	export type Incident = { cause: string; damages: Damage[] };
29	
30	export type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	export type Step = QuoteStep | ClaimStep;
33	
34	export type Item = { type: string } & Record<string, unknown>;
35	
36	export type QuoteResult = { premium: number };
37	
38	export type ClaimResult = { payout: number; remainingCap: number };
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export type ScenarioOutcome = { results: Result[] };
43	
44	// ---------------------------------------------------------------------------
45	// Quoting — what a policy costs the customer.
46	// ---------------------------------------------------------------------------
47	
48	/** Base premium of each insurable item type. */
49	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
50	  sword: 100,
51	  amulet: 60,
52	  staff: 80,
53	  potion: 40,
54	  rune: 25,
55	  moonstone: 25,
56	};
57	
58	/** A block is exactly this many items of one and the same type. */
59	const BLOCK_SIZE = 3;
60	
61	/** Special base premium charged for a complete block, instead of the per-item sum. */
62	const BLOCK_BASE_PREMIUM = 60;
63	
64	/** Number of items of each type on a policy. */
65	const countByType = (items: Item[]): Map<string, number> => {
66	  const counts = new Map<string, number>();
67	  for (const item of items) {
68	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
69	  }
70	  return counts;
71	};
72	
73	/** Base premium of a single item of the given type, before block pricing or surcharge. */
74	const basePremiumOfType = (type: string): number => {
75	  const basePremium = BASE_PREMIUM_BY_TYPE[type];
76	  if (basePremium === undefined) {
77	    throw new Error(`Unknown item type: ${type}`);
78	  }
79	  return basePremium;
80	};
81	
82	/** Base premium for all items of one and the same type. */
83	const groupBasePremium = (type: string, count: number): number =>
84	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
85	
86	/** Base premium of a policy covering the given items. */
87	const calculateBasePremium = (items: Item[]): number =>
88	  [...countByType(items)].reduce(
89	    (total, [type, count]) => total + groupBasePremium(type, count),
90	    0,
91	  );
92	
93	/** Risk surcharge charged on the base premium of a cursed item. */
94	const CURSE_RATE = 0.5;
95	
96	/** Enchantment level from which an item counts as highly enchanted. */
97	const HIGH_ENCHANTMENT_LEVEL = 5;
98	
99	/** Risk surcharge charged on the base premium of a highly enchanted item. */
100	const HIGH_ENCHANTMENT_RATE = 0.3;
101	
102	/** True when the item is enchanted strongly enough to attract the surcharge. */
103	const isHighlyEnchanted = (item: Item): boolean =>
104	  typeof item.enchantment === "number" &&
105	  item.enchantment >= HIGH_ENCHANTMENT_LEVEL;
106	
107	/** Combined rate of the surcharges an item attracts. */
108	const itemSurchargeRate = (item: Item): number => {
109	  const curseRate = item.cursed ? CURSE_RATE : 0;
110	  const enchantmentRate = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_RATE : 0;
111	  return curseRate + enchantmentRate;
112	};
113	
114	/** Surcharges an individual item attracts, charged on its own base premium. */
115	const itemSurcharges = (item: Item): number =>
116	  basePremiumOfType(item.type) * itemSurchargeRate(item);
117	
118	/** Surcharges that attach to individual items rather than to the whole policy. */
119	const calculateItemSurcharges = (items: Item[]): number =>
120	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
121	
122	/** Initial assessment surcharge on a customer's first insurance. */
123	const FIRST_INSURANCE_RATE = 0.1;
124	
125	/** Years of business from which a customer counts as long-standing. */
126	const LOYALTY_YEARS = 2;
127	
128	/** Discount a long-standing customer receives on the policy base premium. */
129	const LOYALTY_RATE = -0.2;
130	
131	/** True when the customer has been with MHPCO long enough to earn the discount. */
132	const isLongStanding = (customer: Customer): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
134	
135	/** Discount on every contract after the customer's first. */
136	const FOLLOW_UP_RATE = -0.15;
137	
138	/** True when this is not the customer's first contract. */
139	const isFollowUpContract = (
140	  _customer: Customer,
141	  previousContracts: number,
142	): boolean => previousContracts > 0;
143	
144	/**
145	 * Rates that attach to the policy as a whole. Each applies to the policy base
146	 * premium; positive rates are surcharges, negative ones discounts.
147	 */
148	const POLICY_RATES: {
149	  rate: number;
150	  applies: (customer: Customer, previousContracts: number) => boolean;
151	}[] = [
152	  { rate: FIRST_INSURANCE_RATE, applies: () => true },
153	  { rate: LOYALTY_RATE, applies: isLongStanding },
154	  { rate: FOLLOW_UP_RATE, applies: isFollowUpContract },
155	];
156	
157	/** Net of every policy-wide rate the customer qualifies for. */
158	const policyRate = (customer: Customer, previousContracts: number): number =>
159	  POLICY_RATES.reduce(
160	    (total, { rate, applies }) =>
161	      applies(customer, previousContracts) ? total + rate : total,
162	    0,
163	  );
164	
165	/** Net policy-wide adjustment, charged on the policy base premium. */
166	const calculatePolicyAdjustment = (
167	  policyBasePremium: number,
168	  customer: Customer,
169	  previousContracts: number,
170	): number => policyBasePremium * policyRate(customer, previousContracts);
171	
172	/** Flat fee added to every premium, regardless of the items insured. */
173	const PROCESSING_FEE = 5;
174	
175	/** Price a policy covering the given items. */
176	const quotePremium = (
177	  items: Item[],
178	  customer: Customer,
179	  previousContracts: number,
180	): number => {
181	  const policyBasePremium = calculateBasePremium(items);
182	  const surcharges = calculateItemSurcharges(items);
183	  const policyAdjustment = calculatePolicyAdjustment(
184	    policyBasePremium,
185	    customer,
186	    previousContracts,
187	  );
188	  return roundPremiumUp(
189	    policyBasePremium + surcharges + policyAdjustment + PROCESSING_FEE,
190	  );
191	};
192	
193	// ---------------------------------------------------------------------------
194	// Claims — what a policy pays out when insured items are damaged.
195	// ---------------------------------------------------------------------------
196	
197	/** Sum insured for each item type, per the MHPCO price list. */
198	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
199	  sword: 1000,
200	  amulet: 600,
201	  staff: 800,
202	  potion: 400,
203	  rune: 250,
204	  moonstone: 250,
205	};
206	
207	/** Excess the claimant bears on every damaged item. */
208	const DEDUCTIBLE = 100;
209	
210	/** A policy pays out at most this multiple of its insurance sum. */
211	const CAP_MULTIPLIER = 2;
212	
213	/** Total sum insured under a policy covering the given items. */
214	const insuranceSum = (items: Item[]): number =>
215	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
216	
217	/** Enchantment level from which damage is only partly reimbursed. */
218	const REDUCED_REIMBURSEMENT_LEVEL = 8;
219	
220	/** Share of the damage MHPCO reimburses on a heavily enchanted item. */
221	const REDUCED_REIMBURSEMENT_RATE = 0.5;
222	
223	/** Share of the damage MHPCO reimburses for the given insured item. */
224	const reimbursementRate = (item: Item): number =>
225	  typeof item.enchantment === "number" &&
226	  item.enchantment >= REDUCED_REIMBURSEMENT_LEVEL
227	    ? REDUCED_REIMBURSEMENT_RATE
228	    : 1;
229	
230	/** What MHPCO owes for a single damaged item, before the cap is considered. */
231	const damagePayout = (damage: Damage, item: Item): number =>
232	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
233	
234	/** A quoted policy, tracked so later claim steps can draw against its cap. */
235	type Policy = { items: Item[]; remainingCap: number };
236	
237	/** The policy a quote step establishes, with its cap untouched. */
238	const openPolicy = (items: Item[]): Policy => ({
239	  items,
240	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
241	});
242	
243	/** The insured item a damage entry refers to. */
244	const damagedItem = (policy: Policy, damage: Damage): Item =>
245	  policy.items.find((item) => item.type === damage.itemType)!;
246	
247	/** What MHPCO owes for an entire incident, before the cap is considered. */
248	const grossIncidentPayout = (incident: Incident, policy: Policy): number =>
249	  incident.damages.reduce(
250	    (total, damage) => total + damagePayout(damage, damagedItem(policy, damage)),
251	    0,
252	  );
253	
254	/**
255	 * Draws an amount owed against the policy's cap. A policy never pays out more
256	 * than the cap it has left, so the amount drawn is whichever is smaller.
257	 */
258	const drawAgainstCap = (policy: Policy, amountOwed: number): number => {
259	  const drawn = Math.min(roundPayoutDown(amountOwed), policy.remainingCap);
260	  policy.remainingCap -= drawn;
261	  return drawn;
262	};
263	
264	// ---------------------------------------------------------------------------
265	// Running a scenario — quote steps open policies, claim steps draw on them.
266	// ---------------------------------------------------------------------------
267	
268	/** True when the step reports damage against a policy rather than asking for a price. */
269	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
270	
271	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
272	  const policies = new Map<number, Policy>();
273	  let previousContracts = 0;
274	
275	  const handleQuote = (step: QuoteStep, stepIndex: number): QuoteResult => {
276	    const premium = quotePremium(
277	      step.items,
278	      scenario.customer,
279	      previousContracts,
280	    );
281	    previousContracts += 1;
282	    policies.set(stepIndex, openPolicy(step.items));
283	    return { premium };
284	  };
285	
286	  const handleClaim = (step: ClaimStep): ClaimResult => {
287	    const policy = policies.get(step.policy)!;
288	    const payout = drawAgainstCap(
289	      policy,
290	      grossIncidentPayout(step.incident, policy),
291	    );
292	    return { payout, remainingCap: policy.remainingCap };
293	  };
294	
295	  const results = scenario.steps.map((step, stepIndex): Result =>
296	    isClaimStep(step) ? handleClaim(step) : handleQuote(step, stepIndex),
297	  );
298	
299	  return { results };
300	};
